// 战前旧档，所持徽记随内存蒸发——主线「星井之守/无字回廊/初灯的审判」（main_cave/main_gallery/main_true
// 均 unlockOn bossDefeated）与真结局（ENDING_TRUE）在自然流程上断链（井巫「井底还在低鸣」/尾声「井，
