  // （守名者支线目标）——此前成就版图里只有侧面纪念（碎片/支线），唯独没有「猎手」这一档；
  // 判定/进度同读 ELITE_GOLEM/EMBER_GOLEM.name（与 withSpecies/图鉴/帮助页同一份精英数据源，
